const panel = document.querySelector('[data-panel-view]')?.closest('aside');
const backdrop = document.querySelector('[data-panel-backdrop]');
const closeButton = document.querySelector('[data-close-panel]');
const panelCompany = document.querySelector('#panel-company');
const navButtons = [...document.querySelectorAll('[data-view]')];
const panelViews = [...document.querySelectorAll('[data-panel-view]')];
const storySearch = document.querySelector('[data-story-search]');
const storyFilterButtons = [
    ...document.querySelectorAll('[data-story-filter]'),
];
const questionInput = document.querySelector('[data-question-input]');
const answerCard = document.querySelector('[data-answer-card]');
const answerContent = document.querySelector('[data-answer-content]');
const citationList = document.querySelector('[data-citation-list]');
const toast = document.querySelector('.toast');

let activeCompanyKey = 'technonext';
let activeStoryFilter = 'recent';
let activeTrigger;
let answerTimer;
let toastTimer;

const setText = (selector, value) => {
    const element = document.querySelector(selector);
    if (element) element.textContent = String(value);
};

const showToast = (message) => {
    window.clearTimeout(toastTimer);
    toast.textContent = message;
    toast.hidden = false;
    toastTimer = window.setTimeout(() => {
        toast.hidden = true;
    }, 2400);
};

const selectView = (viewName, focus = false) => {
    navButtons.forEach((button) => {
        const active = button.dataset.view === viewName;
        button.classList.toggle('is-active', active);
        button.setAttribute('aria-current', active ? 'page' : 'false');
    });
    panelViews.forEach((view) =>
        view.classList.toggle(
            'is-active',
            view.dataset.panelView === viewName
        )
    );

    if (viewName === 'stories' && focus) {
        window.setTimeout(() => storySearch.focus(), 30);
    }
    if (viewName === 'ask' && focus) {
        window.setTimeout(() => questionInput.focus(), 30);
    }
    panel.querySelector('.panel-scroll').scrollTop = 0;
};

const renderThemes = (company) => {
    const container = document.querySelector('[data-theme-list]');
    container.replaceChildren();
    company.themes.forEach(([name, detail, count]) => {
        const row = document.createElement('div');
        row.className = 'theme-row';

        const copy = document.createElement('div');
        const title = document.createElement('strong');
        title.textContent = name;
        const description = document.createElement('span');
        description.textContent = detail;
        copy.append(title, description);

        const value = document.createElement('b');
        value.textContent = String(count);
        value.title = `${count} matching stories in the prototype index`;
        row.append(copy, value);
        container.append(row);
    });
};

const renderSentiment = (company) => {
    const { positive, mixed, negative } = company.sentiment;
    const total = Math.max(positive + mixed + negative, 1);
    document.querySelector('[data-sentiment-positive]').style.width =
        `${(positive / total) * 100}%`;
    document.querySelector('[data-sentiment-mixed]').style.width =
        `${(mixed / total) * 100}%`;
    document.querySelector('[data-sentiment-negative]').style.width =
        `${(negative / total) * 100}%`;
    setText('[data-positive-label]', positive);
    setText('[data-mixed-label]', mixed);
    setText('[data-negative-label]', negative);
};

const currentStoryRows = () => {
    const company = companies[activeCompanyKey];
    const query = storySearch.value.trim().toLowerCase();
    let rows = [...company.storiesList];

    if (activeStoryFilter === 'role') {
        rows = rows.filter((story) =>
            /engineer|manager/i.test(story.role)
        );
    }
    if (activeStoryFilter === 'discussed') {
        rows.sort((left, right) => right.comments - left.comments);
    }
    if (query) {
        rows = rows.filter((story) =>
            `${story.title} ${story.role} ${story.vibe}`
                .toLowerCase()
                .includes(query)
        );
    }
    return rows;
};

const renderStories = () => {
    const container = document.querySelector('[data-source-story-list]');
    const empty = document.querySelector('[data-story-empty]');
    const rows = currentStoryRows();
    container.replaceChildren();
    empty.hidden = rows.length > 0;

    rows.forEach((story) => {
        const article = document.createElement('article');
        article.className = 'source-story';
        const copy = document.createElement('div');
        const title = document.createElement('h4');
        title.textContent = story.title;
        const byline = document.createElement('p');
        byline.textContent = `${story.role} · ${story.date}`;
        const meta = document.createElement('div');
        meta.className = 'story-meta';
        [story.vibe, `↑ ${story.reactions}`, `◌ ${story.comments}`].forEach(
            (value) => {
                const item = document.createElement('span');
                item.textContent = value;
                meta.append(item);
            }
        );
        copy.append(title, byline, meta);

        const link = document.createElement('a');
        link.href = story.url;
        link.target = '_blank';
        link.rel = 'noreferrer';
        link.textContent = '↗';
        link.setAttribute('aria-label', `Open ${story.title}`);
        article.append(copy, link);
        container.append(article);
    });
};

const renderJobs = (company) => {
    const container = document.querySelector('[data-job-list]');
    const status = document.querySelector('[data-hiring-status]');
    const careerLink = document.querySelector('[data-career-link]');
    const websiteLink = document.querySelector('[data-company-website]');
    const linkedinLink = document.querySelector('[data-company-linkedin]');
    const jobsNote = document.querySelector('[data-jobs-note]');
    container.replaceChildren();

    websiteLink.href = company.websiteUrl;
    linkedinLink.href = company.linkedinUrl;
    status.textContent = company.jobsChecked;
    jobsNote.textContent = company.jobsNote;

    if (!company.jobs.length) {
        const empty = document.createElement('p');
        empty.className = 'job-empty';
        empty.textContent =
            'No current, company-specific role is verified in this snapshot.';
        container.append(empty);
        careerLink.href = company.careerUrl || company.linkedinUrl;
        careerLink.textContent = company.careerUrl
            ? 'Check careers'
            : 'Check LinkedIn jobs';
        careerLink.hidden = false;
        renderSalary(company);
        return;
    }

    company.jobs.forEach((job) => {
        const row = document.createElement('a');
        row.className = 'job-row';
        row.href = job.url;
        row.target = '_blank';
        row.rel = 'noreferrer';
        row.setAttribute(
            'aria-label',
            `Open ${job.title} from ${job.source} in a new tab`
        );
        const copy = document.createElement('div');
        const title = document.createElement('strong');
        title.textContent = job.title;
        const location = document.createElement('span');
        location.textContent = `${job.detail} · ${job.source}`;
        copy.append(title, location);
        const type = document.createElement('em');
        type.textContent = job.disclosure;
        row.append(copy, type);
        container.append(row);
    });
    careerLink.href = company.careerUrl;
    careerLink.textContent = 'Open all career listings ↗';
    careerLink.hidden = false;
    renderSalary(company);
};

const renderSalary = (company) => {
    setText('[data-salary-label]', company.salaryEvidence.label);
    setText('[data-salary-status]', company.salaryEvidence.status);
    setText('[data-salary-summary]', company.salaryEvidence.summary);
    setText('[data-salary-source]', company.salaryEvidence.source);
};

const resetAsk = () => {
    window.clearTimeout(answerTimer);
    questionInput.value = '';
    answerCard.hidden = true;
    answerContent.replaceChildren();
    citationList.replaceChildren();
    const action = document.querySelector('[data-answer-action]');
    action.disabled = false;
    action.firstChild.textContent = 'Find answer ';
};

const renderCompany = (companyKey) => {
    const company = companies[companyKey] ?? companies.technonext;
    activeCompanyKey = companies[companyKey] ? companyKey : 'technonext';
    panelCompany.textContent = company.name;
    setText('[data-brief-headline]', company.headline);
    setText('[data-brief-copy]', company.copy);
    setText('[data-metric-stories]', company.stories);
    setText('[data-metric-rating]', company.rating);
    setText('[data-metric-recommend]', company.recommend);
    setText('[data-story-total]', `${company.stories} stories`);
    setText('[data-recent-count]', company.recent);
    setText('[data-recent-note]', company.recentNote);
    renderSentiment(company);
    renderThemes(company);
    renderJobs(company);
    activeStoryFilter = 'recent';
    storySearch.value = '';
    storyFilterButtons.forEach((button) =>
        button.classList.toggle(
            'is-active',
            button.dataset.storyFilter === 'recent'
        )
    );
    renderStories();
    resetAsk();
};

const openPanel = (companyKey, requestedView = 'brief', trigger) => {
    activeTrigger?.setAttribute('aria-expanded', 'false');
    activeTrigger = trigger;
    activeTrigger?.setAttribute('aria-expanded', 'true');
    renderCompany(companyKey);
    selectView(requestedView);
    panel.classList.add('is-open');
    panel.setAttribute('aria-hidden', 'false');
    backdrop.hidden = false;
    document.body.classList.add('panel-is-open');
    requestAnimationFrame(() => backdrop.classList.add('is-open'));
    window.setTimeout(() => closeButton.focus(), 40);
};

const closePanel = () => {
    if (!panel.classList.contains('is-open')) return;
    panel.classList.remove('is-open');
    panel.setAttribute('aria-hidden', 'true');
    backdrop.classList.remove('is-open');
    document.body.classList.remove('panel-is-open');
    activeTrigger?.setAttribute('aria-expanded', 'false');
    activeTrigger?.focus();
    window.setTimeout(() => {
        if (!panel.classList.contains('is-open')) backdrop.hidden = true;
    }, 220);
};

document.querySelectorAll('[data-open-company]').forEach((button) => {
    button.addEventListener('click', () =>
        openPanel(button.dataset.openCompany, 'brief', button)
    );
});

closeButton.addEventListener('click', closePanel);
backdrop.addEventListener('click', closePanel);

navButtons.forEach((button) =>
    button.addEventListener('click', () =>
        selectView(button.dataset.view, true)
    )
);

document
    .querySelector('[data-go-stories]')
    .addEventListener('click', () => selectView('stories', true));
document
    .querySelector('[data-go-ask]')
    .addEventListener('click', () => selectView('ask', true));

storySearch.addEventListener('input', renderStories);
storyFilterButtons.forEach((button) =>
    button.addEventListener('click', () => {
        activeStoryFilter = button.dataset.storyFilter;
        storyFilterButtons.forEach((candidate) =>
            candidate.classList.toggle('is-active', candidate === button)
        );
        renderStories();
    })
);

document
    .querySelectorAll('[data-question-suggestions] button')
    .forEach((button) =>
        button.addEventListener('click', () => {
            questionInput.value = button.textContent;
            questionInput.focus();
        })
    );

document.querySelector('[data-ask-form]').addEventListener('submit', (event) => {
    event.preventDefault();
    if (questionInput.value.trim().length < 8) {
        questionInput.focus();
        showToast('Write a focused question first.');
        return;
    }

    const action = document.querySelector('[data-answer-action]');
    action.disabled = true;
    action.firstChild.textContent = 'Reading stories ';
    answerCard.hidden = true;

    answerTimer = window.setTimeout(() => {
        const company = companies[activeCompanyKey];
        const list = document.createElement('ul');
        company.answer.forEach((item) => {
            const row = document.createElement('li');
            row.textContent = item;
            list.append(row);
        });
        answerContent.replaceChildren(list);
        citationList.replaceChildren();
        company.storiesList.slice(0, 3).forEach((story) => {
            const citation = document.createElement('a');
            citation.href = story.url;
            citation.target = '_blank';
            citation.rel = 'noreferrer';
            citation.textContent = `DM-${story.id}`;
            citation.title = story.title;
            citationList.append(citation);
        });
        answerCard.hidden = false;
        action.disabled = false;
        action.firstChild.textContent = 'Find answer ';
        answerCard.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }, 650);
});

document.addEventListener('keydown', (event) => {
    if (!panel.classList.contains('is-open')) return;
    if (event.key === 'Escape') {
        closePanel();
        return;
    }
    if (event.key !== 'Tab') return;

    const focusable = [
        ...panel.querySelectorAll(
            'button:not([disabled]), a[href], input:not([disabled]), textarea:not([disabled])'
        ),
    ].filter((element) => element.offsetParent !== null);
    if (!focusable.length) return;
    const first = focusable[0];
    const last = focusable[focusable.length - 1];
    if (event.shiftKey && document.activeElement === first) {
        event.preventDefault();
        last.focus();
    } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault();
        first.focus();
    }
});

document.querySelectorAll('a[href="#"]:not([data-career-link])').forEach((link) =>
    link.addEventListener('click', (event) => {
        event.preventDefault();
        showToast('Prototype link — no page was opened.');
    })
);

const params = new URLSearchParams(window.location.search);
const requestedCompany = params.get('company');
const requestedView = params.get('view');
if (requestedCompany || requestedView) {
    openPanel(
        companies[requestedCompany] ? requestedCompany : 'technonext',
        ['brief', 'stories', 'jobs', 'ask'].includes(requestedView)
            ? requestedView
            : 'brief'
    );
}

if (params.get('answer') === 'true') {
    questionInput.value = 'What do engineers report?';
    document.querySelector('[data-ask-form]').requestSubmit();
}
